// ==UserScript==
// @name         Mastodon ACM Computer Modern Font
// @namespace    http://tampermonkey.net/
// @version      2.0
// @description  Make mastodon.acm.org and twiukraine.com use the same "Computer Modern Sans" body font as mathstodon.xyz
// @author       You
// @match        https://mastodon.acm.org/*
// @match        https://twiukraine.com/*
// @run-at       document-start
// @grant        none
// ==/UserScript==

// Mastodon serves a strict CSP: "style-src 'self' 'nonce-...'" blocks any <style>
// element we inject, and "font-src 'self'" blocks data: URI fonts. Two routes get
// around it, both verified in Firefox and Chromium:
//   - a constructed CSSStyleSheet added to document.adoptedStyleSheets is applied
//     through the CSSOM, which CSP does not police
//   - a FontFace built from an ArrayBuffer never performs a fetch, so font-src
//     never comes into play
(function () {
    'use strict';

    const FAMILY = 'Computer Modern Sans';

    // Same CMU Sans Serif webfont mathstodon.xyz serves, as base64 woff.
    const FACES = [
        { weight: '400', style: 'normal', data: '' },
        { weight: '700', style: 'normal', data: '' },
        { weight: '400', style: 'italic', data: '' },
        { weight: '700', style: 'italic', data: '' }
    ];

    for (const face of FACES) {
        const bin = atob(face.data);
        const bytes = new Uint8Array(bin.length);
        for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
        new FontFace(FAMILY, bytes.buffer, { weight: face.weight, style: face.style })
            .load()
            .then(loaded => document.fonts.add(loaded));
    }

    // !important is needed to outrank ".system-font body", which Mastodon applies
    // when the "use system font" appearance preference is on.
    const sheet = new CSSStyleSheet();
    sheet.replaceSync(`body { font-family: "${FAMILY}", mastodon-font-sans-serif, sans-serif !important; }`);
    document.adoptedStyleSheets = [...document.adoptedStyleSheets, sheet];
})();
